fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap()
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    // Handle edge cases first
    if q <= 0 {
        return get_min_val(&a);
    }
    if q >= 100 {
        return get_max_val(&a);
    }
    
    // Sort the array
    let mut sorted = a.clone();
    sorted.sort();
    
    // Calculate the quantile index using linear interpolation
    // Formula: index = (q/100) * (n-1)
    let n = sorted.len() as f64;
    let q_fraction = q as f64 / 100.0;
    let index = q_fraction * (n - 1.0);
    
    // Get the lower and upper indices for interpolation
    let lower_idx = index.floor() as usize;
    let upper_idx = index.ceil() as usize;
    
    // If lower and upper indices are the same, return that element
    if lower_idx == upper_idx {
        return sorted[lower_idx];
    }
    
    // Linear interpolation between the two nearest values
    let lower_val = sorted[lower_idx] as f64;
    let upper_val = sorted[upper_idx] as f64;
    let weight = index - lower_idx as f64;
    
    let result = lower_val + (upper_val - lower_val) * weight;
    
    // Round to nearest integer (i8)
    result.round() as i8
}